import assert from 'node:assert/strict';
import { writeFile, mkdir, symlink } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import ts from 'typescript';
const legacy='c227f8c6ecfe85895937013e4687deb40247a6ee', dir=resolve('.local/legacy-import');
await mkdir(dir);await writeFile(resolve(dir,'package.json'),'{"type":"module"}');await symlink(resolve('packages/persistence/node_modules'),resolve(dir,'node_modules'));
const rows=[];
for(const name of ['store','storage','gate','domain','replay','config']){
 const path='packages/persistence/src/'+name+'.ts';const old=spawnSync('git',['show',legacy+':'+path],{encoding:'utf8'});assert.equal(old.status,0);
 const result=ts.transpileModule(old.stdout,{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022},reportDiagnostics:true});assert.equal(result.diagnostics.filter(d=>d.category===ts.DiagnosticCategory.Error).length,0);
 await writeFile(resolve(dir,name+'.js'),result.outputText);rows.push({path,rawBytes:Buffer.byteLength(old.stdout),rawSHA256:createHash('sha256').update(old.stdout).digest('hex'),compiledSHA256:createHash('sha256').update(result.outputText).digest('hex')});
}
const module=await import(pathToFileURL(resolve(dir,'store.js')).href);assert.equal(typeof module.Persistence,'function');
const source=spawnSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).stdout.trim();const output={sourceSHA:source,legacyCommit:legacy,actualSixGitShowTranspileAndModuleImport:true,constructorInstantiated:false,databaseConnectionsOrQueries:false,providerCalls:false,scope:'Same six old source/transpile/load prerequisites as unchanged formal r4Legacy; actual publication behavior not rerun without PG',rows};
await writeFile(resolve('../legacy-module-load.json'),JSON.stringify(output,null,2)+'\n');console.log('SIX_REAL_LEGACY_MODULES_TRANSPILED_AND_IMPORTED_WITHOUT_DB');
